import { useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../hooks/useAuth";

export default function Connexion() {
  const { login } = useAuth();
  const [email, setEmail] = useState("");
  const [motDePasse, setMotDePasse] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    login({ email, motDePasse });
  };

  return (
    <div style={styles.page}>

      <div style={styles.card}>

        {/* Partie gauche (bleue) */}
        <div style={styles.left}>
          <h2 style={styles.logo}>E-Store</h2>
          <p style={styles.welcome}>Bienvenue 👋</p>
          <p style={styles.desc}>
            Connecte-toi pour accéder à ton compte et tes commandes.
          </p>
        </div>

        {/* Partie droite (formulaire) */}
        <div style={styles.right}>
          <h2 style={styles.title}>Connexion</h2>

          <form onSubmit={handleSubmit} style={styles.form}>
            
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={styles.input}
              required
            />

            <input
              type="password"
              placeholder="Mot de passe"
              value={motDePasse}
              onChange={(e) => setMotDePasse(e.target.value)}
              style={styles.input}
              required
            />

            <button type="submit" style={styles.button}>
              Se connecter
            </button>
          </form>

          <p style={styles.footer}>
            Pas encore de compte ?{" "}
            <Link to="/inscription" style={styles.link}>
              S'inscrire
            </Link>
          </p>
        </div>

      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "#ffffff",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    padding: "20px",
  },

  card: {
    display: "flex",
    width: "800px",
    maxWidth: "100%",
    borderRadius: "16px",
    overflow: "hidden",
    boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
  },

  left: {
    flex: 1,
    background: "#3B5BDB",
    color: "white",
    padding: "40px",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
  },

  logo: {
    fontSize: "24px",
    marginBottom: "20px",
  },

  welcome: {
    fontSize: "22px",
    fontWeight: "bold",
    marginBottom: "10px",
  },

  desc: {
    fontSize: "14px",
    opacity: 0.9,
  },

  right: {
    flex: 1,
    background: "white",
    padding: "40px",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
  },

  title: {
    marginBottom: "20px",
    color: "#333",
  },

  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
  },

  input: {
    padding: "12px",
    borderRadius: "8px",
    border: "1px solid #ddd",
    outline: "none",
  },

  button: {
    marginTop: "10px",
    padding: "12px",
    background: "#3B5BDB",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold",
  },

  footer: {
    marginTop: "20px",
    fontSize: "14px",
    color: "#555",
  },

  link: {
    color: "#3B5BDB",
    fontWeight: "bold",
    textDecoration: "none",
  },
};
